/**
 * WordPress dependencies
 */
import { _x } from '@safe-wordpress/i18n';

/**
 * External dependencies
 */
import type { ConversionAction, ConversionActionTypeRuntime } from '@nab/types';

/**
 * Internal dependencies
 */
import icon from './icon.svg';
import { Edit as edit } from './edit';
import { View as view } from './view';

import type { Attributes } from './types';

export const name = 'nab/custom-event';

export const runtime: ConversionActionTypeRuntime< Attributes > = {
	icon,
	validate: ( { snippet = '' } ) =>
		! /\bconvert\s*()\b/.test( snippet )
			? {
					snippet: _x(
						'Call function convert() at least once',
						'user',
						'nelio-ab-testing'
					),
				}
			: {},
	edit,
	view,
};

// ==========
// TYPESCRIPT
// ==========

declare module '@nab/conversion-actions' {
	// eslint-disable-next-line @typescript-eslint/ban-ts-comment
	// @ts-ignore

	function createConversionAction(
		actionType: typeof name,
		attributes: Partial< Attributes >
	): ConversionAction< Attributes >;
}
